#include <iostream>
#include <algorithm>
using namespace std;

long long recursiveSolve(long long x) {
    if (x == 0) return 0;
    long long power = 1, length = 1;
    while (power <= x) {
        power = power * 10 + 1;
        length++;
    }
    length--;
    power = (power - 1) / 10;
    if (power == x) return length;
    long long minSteps = (1LL << 61);
    if ((power * 10 + 1 - x) < x) {
        minSteps = recursiveSolve(power * 10 + 1 - x) + length + 1;
    }
    long long maxFactor = 1;
    long long candidate;
    while (power * maxFactor <= x) {
        candidate = power * maxFactor;
        maxFactor++;
    }
    maxFactor--;
    long long option = recursiveSolve(x - candidate) + length * (maxFactor - 1);
    return min(minSteps, option);
}

int main() {
    ios::sync_with_stdio(false);
    long long inputNumber;
    cin >> inputNumber;
    cout << recursiveSolve(inputNumber);
    return 0;
}
